      "finding_id": "DD-1",
      "drift_kind": "signature",
      "explanation": "The parse_tuple docstring refers to a `no_condexpr` parameter, but the method declares and forwards `with_condexpr`.",
      "doc_citation": {
        "path": "jinja/src/jinja2/parser.py",
        "start_line": 694,
        "end_line": 697,
        "quote": "        The default parsing mode is a full tuple.  If `simplified` is `True`\n        only names and literals are parsed; ``with_namespace`` allows namespace\n        attr refs as well. The `no_condexpr` parameter is forwarded to\n        :meth:`parse_expression`."
      },
      "code_citation": {
        "path": "jinja/src/jinja2/parser.py",
        "start_line": 684,
        "end_line": 684,
        "quote": "        with_condexpr: bool = True,"
      },
      "proposed_fix": "Replace `no_condexpr` with `with_condexpr` in the parse_tuple docstring."
    },
    {
      "finding_id": "DD-2",
      "drift_kind": "other",
      "explanation": "The Cookie.value field is documented as describing the cookie key, contradicting its field name.",
      "doc_citation": {
        "path": "werkzeug/src/werkzeug/test.py",
        "start_line": 1384,
        "end_line": 1384,
        "quote": "    \"\"\"The cookie key, encoded as a client would see it.\"\"\""
      },
      "code_citation": {
        "path": "werkzeug/src/werkzeug/test.py",
        "start_line": 1383,
        "end_line": 1383,
        "quote": "    value: str"
      },
      "proposed_fix": "Change the docstring for Cookie.value to describe the cookie value rather than the key."
    }
  ],
  "atlas_claims": []
